package com.bank.pool.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "payments")
public class Payment {
    @Id @Column(name = "payment_id") private String paymentId;
    @Column(name = "account_id") private String accountId;
    private BigDecimal amount;
    private String status;
    @Column(name = "created_at") private LocalDateTime createdAt;

    protected Payment() {}

    public Payment(String paymentId, String accountId, BigDecimal amount) {
        this.paymentId = paymentId;
        this.accountId = accountId;
        this.amount = amount;
        this.status = "PENDING";
        this.createdAt = LocalDateTime.now();
    }

    public void complete() { this.status = "COMPLETED"; }
    public String getPaymentId() { return paymentId; }
}
