// REQUIRES_NEW: needs a SECOND connection from pool
package com.bank.pool.service;

import com.bank.pool.model.AuditLog;
import com.bank.pool.repository.AuditRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class AuditService {

    private final AuditRepository auditRepo;

    /**
     * REQUIRES_NEW: suspends outer TX, gets SECOND connection from pool.
     *
     * CONNECTION LIFECYCLE:
     * 1. Outer TX holds connection #1 (SUSPENDED — NOT released!)
     * 2. This method gets connection #2 from HikariCP
     * 3. INSERT audit record on connection #2
     * 4. COMMIT connection #2 → returned to pool
     * 5. Outer TX RESUMED on connection #1
     *
     * DEADLOCK SCENARIO (pool=10, threads=10):
     * All 10 threads hold connection #1.
     * All 10 call this method → need connection #2.
     * Pool has 0 available. All 10 wait. Nobody releases. DEADLOCK!
     */
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void logPayment(String paymentId, String status) {
        String threadName = Thread.currentThread().getName();
        log.info("[AUDIT] [{}] REQUIRES_NEW — getting 2nd connection for {}", threadName, paymentId);
        auditRepo.save(new AuditLog(paymentId, "PAYMENT", status));
        log.info("[AUDIT] [{}] Committed independently for {}", threadName, paymentId);
    }
}
