import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {

    @Mock PaymentRepository paymentRepo;
    @Mock AuditService auditService;
    @InjectMocks PaymentService paymentService;

    @Test
    void shouldProcessPaymentAndAudit() {
        when(paymentRepo.save(any(Payment.class))).thenAnswer(i -> i.getArgument(0));

        String paymentId = paymentService.processPayment("SAV2001", new BigDecimal("50000"));

        assertThat(paymentId).startsWith("PAY-");
        verify(paymentRepo).save(any(Payment.class));
        verify(auditService).logPayment(eq(paymentId), eq("COMPLETED"));
    }
}
